// Obtener todos los datos de las hojas
const areasData = $('Read Areas').all();
const modulosData = $('Read Modulos').all();
const topicsData = $('Read Topics').all();
const recursosData = $('Read Recursos').all();

// Extraer JSON de cada fuente
const areas = areasData.map(item => item.json);
const modulos = modulosData.map(item => item.json);
const topics = topicsData.map(item => item.json);
const recursos = recursosData.map(item => item.json);

// Función para limpiar y normalizar datos
const cleanData = (arr) => {
  return arr.map(item => {
    const cleaned = {};
    for (const [key, value] of Object.entries(item)) {
      if (value === 'TRUE' || value === 'true') cleaned[key] = true;
      else if (value === 'FALSE' || value === 'false') cleaned[key] = false;
      else if (value === '' || value === null || value === undefined) cleaned[key] = null;
      else if (!isNaN(value) && value !== '') cleaned[key] = Number(value);
      else cleaned[key] = value;
    }
    return cleaned;
  });
};

const cleanedAreas = cleanData(areas);
const cleanedModulos = cleanData(modulos);
const cleanedTopics = cleanData(topics);
const cleanedRecursos = cleanData(recursos);

// Crear el objeto de sincronización completo
const syncPayload = {
  sync_type: 'full',
  timestamp: new Date().toISOString(),
  action: 'sync_all',
  source: 'google_sheets',
  spreadsheet_id: '15Zpa7kkkGf6PeEIADg1Y4uusS-G-mtms6p_i2WS-k-8',
  data: {
    areas: cleanedAreas,
    modulos: cleanedModulos,
    topics: cleanedTopics,
    recursos: cleanedRecursos
  },
  statistics: {
    areas_count: cleanedAreas.length,
    modulos_count: cleanedModulos.length,
    topics_count: cleanedTopics.length,
    recursos_count: cleanedRecursos.length,
    total_records: cleanedAreas.length + cleanedModulos.length + cleanedTopics.length + cleanedRecursos.length
  }
};

return [{ json: syncPayload }];

