const progress_pct = body.progress_pct !== undefined ? Number(body.progress_pct) : (status === 'COMPLETADO' ? 100 : 0);
const quiz_score = body.quiz_score !== undefined && body.quiz_score !== null && body.quiz_score !== '' ? Number(body.quiz_score) : '';
