const p = $node['Code - Normalize Topic Payload'].json;
const rows = $items('Google Sheets - Read Empleado_Topic_Progreso').map(i => i.json);
const found = rows.find(r =>
  (r.employee_id || r.empleado_id || '') === p.employee_id &&
  (r.modulo_id || '') === p.modulo_id &&
  (r.topic_id || '') === p.topic_id
);
return [{ json: { ...p, topic_exists: !!found } }];

const ev = $node['Code - Normalize Topic Payload'].json;
const rows = $items('Google Sheets - Read Empleado_Topic_Progreso (Recalc)').map(i => i.json)
  .filter(r => (r.employee_id || r.empleado_id || '') === ev.employee_id && (r.modulo_id || '') === ev.modulo_id);

const topics_total = rows.length;
const topics_completados = rows.filter(r => String(r.status || '').toUpperCase() === 'COMPLETADO').length;
const progreso_pct = topics_total ? Math.round((topics_completados / topics_total) * 100) : 0;

const scores = rows
  .map(r => Number(r.quiz_score))
  .filter(n => !Number.isNaN(n) && Number.isFinite(n));
const quiz_score_avg = scores.length ? Math.round(scores.reduce((a,b)=>a+b,0)/scores.length) : 0;

const quiz_intentos = rows.reduce((acc, r) => acc + (Number(r.attempts || 0) || 0), 0);

let status = 'NO_INICIADO';
if (progreso_pct >= 100) status = 'COMPLETADO';
else if (progreso_pct > 0) status = 'EN_PROGRESO';

const last_activity_at = rows
  .map(r => r.last_activity_at)
  .filter(Boolean)
  .sort()
  .reverse()[0] || ev.last_activity_at;

const now = new Date();
const last = last_activity_at ? new Date(last_activity_at) : null;
if (status === 'EN_PROGRESO' && last && (now - last) / (1000*60*60*24) >= 3 && progreso_pct < 30) {
  status = 'EN_RIESGO';
}

return [{
  json: {
    employee_id: ev.employee_id,
    modulo_id: ev.modulo_id,
    modulo_nombre: ev.modulo_nombre,
    area_id: ev.area_id,
    assigned_at: '',
    started_at: progreso_pct > 0 ? (rows.map(r => r.last_activity_at).filter(Boolean).sort()[0] || ev.last_activity_at) : '',
    completed_at: status === 'COMPLETADO' ? (rows.map(r => r.completed_at).filter(Boolean).sort().reverse()[0] || ev.last_activity_at) : '',
    status,
    progreso_pct,
    topics_total,
    topics_completados,
    quiz_score_avg,
    quiz_intentos,
    last_activity_at,
    next_review_at: '',
    updated_at: new Date().toISOString()
  }
}];

const m = $node['Code - Recalculate Module Progress'].json;
const rows = $items('Google Sheets - Read Empleado_Modulo_Progreso2').map(i => i.json);
const found = rows.find(r =>
  (r.employee_id || r.empleado_id || '') === m.employee_id &&
  (r.modulo_id || '') === m.modulo_id
);
return [{ json: { ...m, module_exists: !!found } }];

