function makeId(prefix = "") {
  if (globalThis.crypto?.randomUUID) return prefix + globalThis.crypto.randomUUID();
  const rnd = () => Math.floor(Math.random() * 1e9).toString(16).padStart(8, "0");
  const t = Date.now().toString(16);
  return prefix + `${t}-${rnd()}-${rnd()}-${rnd()}`;
}

function bytesToBase64(bytes) {
  let binary = "";
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode(...bytes.slice(i, i + chunkSize));
  }
  return btoa(binary);
}

function strToBytes(str) {
  return new TextEncoder().encode(str);
}

async function pbkdf2Hash(password, saltBytes, iterations = 210000, dkLen = 32) {
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    strToBytes(password),
    { name: "PBKDF2" },
    false,
    ["deriveBits"]
  );

  const derivedBits = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      salt: saltBytes,
      iterations,
      hash: "SHA-256",
    },
    keyMaterial,
    dkLen * 8
  );

  return new Uint8Array(derivedBits);
}

// Puede venir como { body: [...] } o directamente [...]
const raw = $json.body ?? $json;
const body = Array.isArray(raw) ? raw[0] : raw;

const email = (body.email || "").trim().toLowerCase();
if (!email) throw new Error("Falta email");

const password = (body.password || "").toString();
if (!password) throw new Error("Falta password (admin debe asignarlo)");

const empleado_id = makeId("emp_");
const auth_token = makeId("tok_");
const token_expires = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();

const area = (body.area || "").trim();
const rol = (body.rol || "").trim();
const estado_global = (body.estado_global || "ACTIVO").toString().trim().toUpperCase();

// ✅ Hash PBKDF2
const salt = new Uint8Array(16);
crypto.getRandomValues(salt);
const iterations = 210000;
const dkLen = 32;

const hashBytes = await pbkdf2Hash(password, salt, iterations, dkLen);

const password_hash = [
  "pbkdf2",
  "sha256",
  iterations,
  bytesToBase64(salt),
  bytesToBase64(hashBytes),
].join("$");

const password_updated_at = new Date().toISOString();
const must_change_password = body.must_change_password ?? 1;

return [{
  json: {
    empleado_id,
    nombre: (body.nombre || "").trim(),
    email,
    rol,
    area,
    fecha_inicio: (body.fecha_inicio || "").trim(),
    manager_email: (body.manager_email || "").trim().toLowerCase(),
    test_url: (body.evaluacion_url || "").trim().toLowerCase(),
    estado_global,
    auth_token,
    token_expires,
    meta_certificacion_pct: body.meta_certificacion_pct ?? 85,
    last_activity_at: body.last_activity_at || new Date().toISOString(),

    // 👇 nuevos campos en Empleados
    password_hash,
    password_updated_at,
    must_change_password,

    _perm: {
      employee_id: empleado_id,
      email,
      role: rol,
      area_id: area,
      enabled: (body.enabled ?? true) ? "true" : "false",
      granted_by: "SYSTEM",
      granted_at: new Date().toISOString(),
      notes: body.cohort ? `cohort=${body.cohort}` : ""
    }
  }
}];

const { passwordIn, storedHash, nowMs, newToken, newTokenExpires, emp } = $json;

function base64ToBytes(b64) {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

async function pbkdf2Verify(password, stored) {
  const parts = stored.split("$");
  if (parts.length !== 5) throw new Error("Formato de hash inválido");
  const [, , iterStr, b64Salt, b64Hash] = parts;
  const iterations   = parseInt(iterStr, 10);
  const salt         = base64ToBytes(b64Salt);
  const expectedHash = base64ToBytes(b64Hash);

  const keyMaterial = await crypto.subtle.importKey(
    "raw", new TextEncoder().encode(password),
    { name: "PBKDF2" }, false, ["deriveBits"]
  );
  const derivedBits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", salt, iterations, hash: "SHA-256" },
    keyMaterial, expectedHash.length * 8
  );
  const derived = new Uint8Array(derivedBits);
  if (derived.length !== expectedHash.length) return false;
  let diff = 0;
  for (let i = 0; i < derived.length; i++) diff |= derived[i] ^ expectedHash[i];
  return diff === 0;
}

const passwordOk = await pbkdf2Verify(passwordIn, storedHash);
if (!passwordOk) {
  return [{ json: { ok: false, status: 401, message: "Contraseña incorrecta" } }];
}

// Token
const rawRole = (emp.rol || "empleado").toString().trim().toLowerCase();
const role    = rawRole === "admin" ? "admin" : "empleado";

let token         = (emp.auth_token    || "").toString().trim();
let token_expires = (emp.token_expires || "").toString().trim();

const expDate  = token_expires ? new Date(token_expires) : null;
const expValid = expDate && expDate.toString() !== "Invalid Date" && expDate.getTime() > Number(nowMs);

if (!token || !expValid) {
  token         = newToken;
  token_expires = newTokenExpires;
}

const redirect = role === "admin" ? "/admin/dashboard" : "/empleado/dashboard";

return [{
  json: {
    ok: true,
    empleado_id:            emp.empleado_id || "",
    nombre:                 emp.nombre      || "",
