    role,
    area:                   emp.area        || "",
    estado_global:          emp.estado_global,
    meta_certificacion_pct: Number(emp.meta_certificacion_pct || 85),
    must_change_password:   emp.must_change_password == "1" || emp.must_change_password === true,
    token,
    token_expires,
    redirect,
    _update: {
      empleado_id:      emp.empleado_id || "",
      auth_token:       token,
      token_expires,
      last_activity_at: new Date().toISOString()
    }
  }
}];

